/**
 * Post-process files generated by `shadcn add`.
 *
 * shadcn 4.21 resolves `aliases.utils` to a bare module specifier and emits
 * `import { cn } from "cn"`, which does not resolve at build time. Our canonical
 * location is `src/lib/utils.ts` (aliased as `@/lib/utils`), so rewrite the
 * import to point there.
 *
 * Idempotent: re-running on already-correct files is a no-op.
 *
 * Usage: node scripts/fix-shadcn-imports.mjs [paths...]
 */
import { readFile, readdir, writeFile } from 'node:fs/promises'
import { extname, join, resolve } from 'node:path'

const BAD = /(\bfrom\s+|\bimport\s+)(["'])cn\2/g
const GOOD = '$1$2@/lib/utils$2'

const SKIP_DIRS = new Set(['node_modules', 'dist', '.git'])

/** @param {string} dir @returns {Promise<string[]>} */
async function walk(dir) {
  /** @type {string[]} */
  const out = []
  let entries
  try {
    entries = await readdir(dir, { withFileTypes: true })
  } catch {
    return out
  }
  for (const entry of entries) {
    const full = join(dir, entry.name)
    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(entry.name)) continue
      out.push(...(await walk(full)))
    } else if (['.ts', '.tsx', '.js', '.jsx'].includes(extname(entry.name))) {
      out.push(full)
    }
  }
  return out
}

const targets = process.argv.length > 2 ? process.argv.slice(2) : ['src']
const files = (await Promise.all(targets.map((t) => walk(resolve(t))))).flat()

let fixed = 0
for (const file of files) {
  const source = await readFile(file, 'utf8')
  if (!BAD.test(source)) continue
  BAD.lastIndex = 0
  await writeFile(file, source.replace(BAD, GOOD), 'utf8')
  console.log(`  fixed  ${file}`)
  fixed += 1
}

console.log(fixed ? `\nshadcn import fix: ${fixed} file(s) updated` : 'shadcn import fix: nothing to do')
